ee:variables.ee:set-variable:
%dw 2.0
output application/json

var invoice = vars.initialPayload[0].b2bMessage
var header = invoice.header
var summaryData = invoice.summary
var lines = invoice.detail.invoice.itemDetails default []
var poLines = vars.purchaseOrderData.value

// ---------- Step 1: Carrier ID presence ----------
var carrierId = (summaryData.carrierDetail.carrierCode default "") as String
var isCarrierPresent = !isEmpty(trim(carrierId))

// ---------- Step 2: Festo Freight Value ----------
var festoFreightValue = summaryData.serviceAllowanceCharge.adjustmentAmount default 0

// ---------- Step 3: Tier-based flat rate markup ----------
fun tierFlatRate(amount: Number): Number =
  if (amount >= 1000) 20.00
  else if (amount >= 500) 18.00
  else if (amount >= 100) 14.00
  else if (amount >= 50) 8.00
  else if (amount >= 0.01) 6.00
  else 0.00

// ---------- Step 4: Apply Scenario Rules ----------
var itemBillAmount = summaryData.totalAmount default 0

var scenarioCode =
  if (isCarrierPresent) "SC1"
  else if (festoFreightValue >= 100) "SC2"
  else "SC3"

var finalFreight =
  if (scenarioCode == "SC1") festoFreightValue
  else if (scenarioCode == "SC2") festoFreightValue
  else festoFreightValue + tierFlatRate(itemBillAmount)

// ---------- Step 5: Normalize + strip "FES" prefix ----------
fun normalize(s: String): String =
  upper(trim(s default ""))

fun stripFesPrefix(partNo: String): String = do {
  var norm = normalize(partNo)
  ---
  if (norm startsWith "FES") norm[3 to -1] else norm
}

// ---------- Step 6: Match invoice lines to P21 PO lines ----------
var matchedItems = lines map ((line) -> do {
    var vendorPartNoNorm = normalize(line.vendorPartNo)
    var poLine = (poLines filter (
        stripFesPrefix($.supplier_part_no) == vendorPartNoNorm
      ))[0]
    ---
    {
      item_id: poLine.item_id default null,
      unit_quantity:  if (poLine.unit_quantity != null)
            poLine.unit_quantity as Number {format: "0.00"}
        else
            null
    }
})

// ---------- Step 7: Assemble Output ----------
var poNoNum = header.poNumber as Number default null
---
{
  po_no: poNoNum,
  tracking_no: summaryData.carrierDetail.trackingNumber default null,
  freight_cd: "CPO",
  receipt_freight: finalFreight[0],
  items: matchedItems
}

%dw 2.0
output application/json

---
{

    Description: null,
    UseCodeValues: true,
    IgnoreDisabled: true,
    Transactions: [
        {
            Status: "New",
            DataElements: [
                {
                    Name: "TABPAGE_1.tp_1_dw_po",
                    BusinessObjectName: null,
                    Type: "Form",
                    Keys: ["po_no"],
                    Rows: [
                        {
                            Edits: [
                                {
                                    Name: "po_no",
                                    Value: vars.isValid.po_no as String,
                                    IgnoreIfEmpty: true
                                },
                                {
                                    Name: "tracking_no",
                                    Value: vars.isValid.tracking_no,
                                    IgnoreIfEmpty: true
                                }
                            ],
                            RelativeDateEdits: []
                        }
                    ]
                },
                {
                    Name: "TABPAGE_FREIGHT.tabpage_freight",
                    BusinessObjectName: null,
                    Type: "Form",
                    Keys: [],
                    Rows: [
                        {
                            Edits: [
                                {
                                    Name: "freight_cd",
                                    Value: vars.isValid.freight_cd,
                                    IgnoreIfEmpty: true
                                },
                                {
                                    Name: "receipt_freight",
                                    Value: (vars.isValid.receipt_freight as Number) as String {
                                        format: "0.00"
                                    },
                                    IgnoreIfEmpty: true
                                }
                            ],
                            RelativeDateEdits: []
                        }
                    ]
                },
                {
                    Name: "TABPAGE_17.tp_17_dw_17",
                    BusinessObjectName: null,
                    Type: "List",
                    Keys: ["item_id"],
                    Rows: vars.isValid.items map (item) -> {
                        Edits: [
                            {
                                Name: "item_id",
                                Value: item.item_id,
                                IgnoreIfEmpty: true
                            },
                            {
                                Name: "unit_quantity",
                                Value: (item.unit_quantity as Number) as String {
                                    format: "0.00"
                                },
                                IgnoreIfEmpty: true
                            }
                        ],
                        RelativeDateEdits: []
                    }
                }
            ],
            Documents: null
        }
    ],
    Query: null,
    FieldMap: [],
    TransactionSplitMethod: 0,
    Parameters: null
}

%dw 2.0
output application/json
import toBase64 from dw::core::Binaries
---
{
	"method": Mule::p('b2b-p21-sys-api.transaction.method'),
	"host": Mule::p('b2b-p21-sys-api.host'),
	"port": Mule::p('b2b-p21-sys-api.port'),
	"basePath": Mule::p('b2b-p21-sys-api.basePath'),
